// Hand-written `@types/aws-lambda` stub for the flowatlas fixture suite: only
// the event shapes the fixture's handlers are given.

export interface APIGatewayProxyEvent {
  body: string | null;
  headers: Record<string, string | undefined>;
  path: string;
  pathParameters: Record<string, string | undefined> | null;
}
export interface APIGatewayProxyResult {
  statusCode: number;
  headers?: Record<string, string>;
  body: string;
}
export interface APIGatewayProxyEventV2 {
  body?: string;
  headers: Record<string, string | undefined>;
  rawPath: string;
  pathParameters?: Record<string, string | undefined>;
  queryStringParameters?: Record<string, string | undefined>;
}
export interface APIGatewayProxyResultV2 {
  statusCode: number;
  headers?: Record<string, string>;
  body: string;
}
export interface APIGatewayProxyWebsocketEventV2 {
  body?: string;
  requestContext: { routeKey: string; connectionId: string };
}
export type LambdaFunctionURLEvent = APIGatewayProxyEventV2;
export type LambdaFunctionURLResult = APIGatewayProxyResultV2;
export interface SQSRecord {
  messageId: string;
  body: string;
}
export interface SQSEvent {
  Records: SQSRecord[];
}
export interface SNSEvent {
  Records: { Sns: { Message: string; TopicArn: string } }[];
}
export interface EventBridgeEvent<TDetailType extends string, TDetail> {
  source: string;
  'detail-type': TDetailType;
  detail: TDetail;
}
export interface ScheduledEvent {
  time: string;
}
export interface DynamoDBRecord {
  eventName?: 'INSERT' | 'MODIFY' | 'REMOVE';
  dynamodb?: { Keys?: Record<string, { S?: string; N?: string }> };
}
export interface DynamoDBStreamEvent {
  Records: DynamoDBRecord[];
}
export interface S3Event {
  Records: { s3: { bucket: { name: string }; object: { key: string } } }[];
}
